			IRI second = vf.createIRI("urn:retire-pressure:second");
			IRI predicate = vf.createIRI("urn:retire-pressure:predicate");
			try (SailConnection seed = store.getConnection()) {
				seed.begin();
				seed.addStatement(first, predicate, vf.createLiteral("first value"));
				seed.addStatement(second, predicate, vf.createLiteral("second value"));
				seed.commit();
			}
			ValueStore values = (ValueStore) store.getValueFactory();
			assertTrue(values.isValueReclamationEnabled());
			long firstId = values.getId(first);
