					assertNotNull(retained);
					assertTrue(retained.ids.containsAll(originalBatch.ids), "every original retirement must remain");
					assertTrue(retirementKeys(retained).containsAll(originalKeys),
							"every original queue key must remain");
					for (Map.Entry<Long, Value> entry : originalValues.entrySet()) {
						assertEquals(entry.getValue(), values.getValue(entry.getKey()),
								"capacity pressure must not reclaim any pending value");
					}
					assertEquals(firstId, values.getId(first), "capacity pressure must not reclaim the old subject");
