	private static Set<String> retirementKeys(RetiredValueIdStore.DrainBatch batch) {
		Set<String> keys = new HashSet<>();
		for (byte[] key : batch.matchedSeqKeys) {
			keys.add(HexFormat.of().formatHex(key));
		}
		for (byte[] key : batch.staleSeqKeys) {
			keys.add(HexFormat.of().formatHex(key));
		}
		return keys;
	}

